 private void load(){loading.setVisibility(View.VISIBLE);status.setText("Duke ngarkuar playlistën…");worker.execute(()->{try{Catalog c=builtIn?new TrialCatalogSource().load(this):engine.load(this,p);Map<String,List<StreamItem>> items=new HashMap<>();Map<String,Integer> counts=new HashMap<>();List<Category> liveCats=c.categories(CatalogType.LIVE);for(Category z:liveCats){List<StreamItem> li=c.items(CatalogType.LIVE,z.id);items.put(z.id,li);counts.put(z.id,li.size());}List<CountryGroup> grouped=CountryResolver.groups(liveCats);runOnUiThread(()->{loading.setVisibility(View.GONE);catalog=c;liveItems.clear();liveItems.putAll(items);liveCounts.clear();liveCounts.putAll(counts);countries=new ArrayList<>(grouped);countrySpinner.setAdapter(spinnerAdapter(countryLabels()));if(!countries.isEmpty()){String wantedCategory=getIntent().getStringExtra("open_category_id"),wantedStream=getIntent().getStringExtra("open_stream_id");int cp=0;for(int n=0;n<countries.size();n++){for(Category z:countries.get(n).categories)if(z.id.equals(wantedCategory)){cp=n;break;}}countrySpinner.setSelection(cp);selectCountry(cp);if(wantedCategory!=null){for(int n=0;n<categories.size();n++)if(categories.get(n).id.equals(wantedCategory)){selectCategory(n,false);break;}if(wantedStream!=null){for(int n=0;n<shown.size();n++)if(shown.get(n).id.equals(wantedStream)){activateChannel(n,false);break;}}}else countrySpinner.requestFocus();}});}catch(Exception e){runOnUiThread(()->{loading.setVisibility(View.GONE);String msg=e.getMessage()==null?"Catalog error":e.getMessage();status.setText(msg);Toast.makeText(this,msg,Toast.LENGTH_LONG).show();});}});}
