 private void selectCountry(int pos){if(pos<0||pos>=countries.size())return;country=countries.get(pos);categories=new ArrayList<>(country.categories);List<String>x=categoryLabels();categoriesView.setAdapter(adapter(x));overlayCategories.setAdapter(adapter(x));channels=Collections.emptyList();shown=new ArrayList<>();channelsView.setAdapter(channelAdapter());overlayChannels.setAdapter(channelAdapter());if(!x.isEmpty()){categoriesView.setSelection(0);selectCategory(0,false);}}
