 private void activateChannel(int pos,boolean fromOverlay){if(pos<0||pos>=shown.size())return;StreamItem item=shown.get(pos);if(current!=null&&current.id.equals(item.id)&&lastResolved!=null&&lastResolved.url!=null&&!lastResolved.url.trim().isEmpty()){if(fromOverlay)hideOverlay();playerView.requestFocus();return;}play(pos,fromOverlay);if(!fromOverlay){fullscreen=false;playerView.setResizeMode(androidx.media3.ui.AspectRatioFrameLayout.RESIZE_MODE_FIT);}}
 private void play(int pos,boolean fromOverlay){if(pos<0||pos>=shown.size())return;recoveryCount=0;recoveryRunning=false;vlcFallbackTried=false;ijkFallbackTried=false;usingVlc=false;usingIjk=false;if(vlcPlayer!=null){try{vlcPlayer.stop();}catch(Exception ignored){}}if(vlcSurface!=null)vlcSurface.setVisibility(View.GONE);if(ijkPlayer!=null){try{ijkPlayer.stop();}catch(Exception ignored){}}if(ijkSurface!=null)ijkSurface.setVisibility(View.GONE);playerView.setVisibility(View.VISIBLE);StreamItem item=shown.get(pos);loading.setVisibility(View.VISIBLE);worker.execute(()->{try{ResolvedStream r=builtIn?new ResolvedStream(item.streamUrl,item.type.name(),item.name,item.logo,item.tvgId,null,null):engine.resolveStream(p,item);runOnUiThread(()->{playResolved(item,r);if(fromOverlay)hideOverlay();});}catch(Exception e){runOnUiThread(()->{loading.setVisibility(View.GONE);Toast.makeText(this,"Stream error",Toast.LENGTH_SHORT).show();});}});}
