 private void playVlc(StreamItem item,ResolvedStream r){try{usingVlc=true;usingIjk=false;player.stop();playerView.setVisibility(View.GONE);if(vlcSurface==null){vlcSurface=new android.view.SurfaceView(this);android.view.ViewGroup parent=(android.view.ViewGroup)playerView.getParent();int idx=parent.indexOfChild(playerView);parent.addView(vlcSurface,idx,playerView.getLayoutParams());vlcSurface.setClickable(true);vlcSurface.setFocusable(true);vlcSurface.setOnClickListener(v->{if(fullscreen)toggleOverlay();else setFullscreen(true);});vlcSurface.setOnTouchListener((v,e)->{if(e.getAction()==android.view.MotionEvent.ACTION_UP){v.performClick();return true;}return true;});}vlcSurface.setVisibility(View.VISIBLE);if(vlc==null)vlc=new org.videolan.libvlc.LibVLC(this,new java.util.ArrayList<String>());if(vlcPlayer==null)vlcPlayer=new org.videolan.libvlc.MediaPlayer(vlc);vlcPlayer.getVLCVout().setVideoView(vlcSurface);vlcPlayer.getVLCVout().attachViews();org.videolan.libvlc.Media media=new org.videolan.libvlc.Media(vlc,android.net.Uri.parse(r.url));for(java.util.Map.Entry<String,String> h:r.headers.entrySet()){String k=h.getKey()==null?"":h.getKey().trim(),v=h.getValue();if(v==null)continue;if(k.equalsIgnoreCase("User-Agent"))media.addOption(":http-user-agent="+v);else if(k.equalsIgnoreCase("Referer")||k.equalsIgnoreCase("Referrer"))media.addOption(":http-referrer="+v);else if(k.equalsIgnoreCase("Cookie"))media.addOption(":http-cookie="+v);}media.addOption(":network-caching=1500");vlcPlayer.setMedia(media);media.release();vlcPlayer.setEventListener(e->{if(e.type==org.videolan.libvlc.MediaPlayer.Event.EncounteredError&&!ijkFallbackTried&&lastResolved!=null){ijkFallbackTried=true;runOnUiThread(()->playIjk(current,lastResolved));}});vlcPlayer.play();loading.setVisibility(View.GONE);}catch(Exception e){usingVlc=false;if(vlcSurface!=null)vlcSurface.setVisibility(View.GONE);playerView.setVisibility(View.VISIBLE);Log.e("LazyTV-VLC","VLC fallback failed",e);}}
 private void playIjk(StreamItem item,ResolvedStream r){try{usingIjk=true;usingVlc=false;if(vlcPlayer!=null)vlcPlayer.stop();if(vlcSurface!=null)vlcSurface.setVisibility(View.GONE);player.stop();playerView.setVisibility(View.GONE);if(ijkSurface==null){ijkSurface=new android.view.SurfaceView(this);android.view.ViewGroup parent=(android.view.ViewGroup)playerView.getParent();int idx=parent.indexOfChild(playerView);parent.addView(ijkSurface,idx,playerView.getLayoutParams());ijkSurface.setClickable(true);ijkSurface.setOnClickListener(v->{if(fullscreen)toggleOverlay();else setFullscreen(true);});}ijkSurface.setVisibility(View.VISIBLE);if(ijkPlayer!=null){try{ijkPlayer.release();}catch(Exception ignored){}}ijkPlayer=new tv.danmaku.ijk.media.player.IjkMediaPlayer();ijkPlayer.setOption(tv.danmaku.ijk.media.player.IjkMediaPlayer.OPT_CATEGORY_PLAYER,"mediacodec",1);ijkPlayer.setOption(tv.danmaku.ijk.media.player.IjkMediaPlayer.OPT_CATEGORY_FORMAT,"timeout",15000000L);ijkPlayer.setOption(tv.danmaku.ijk.media.player.IjkMediaPlayer.OPT_CATEGORY_FORMAT,"reconnect",1);ijkPlayer.setDisplay(ijkSurface.getHolder());java.util.Map<String,String> h=new java.util.LinkedHashMap<>(r.headers);ijkPlayer.setDataSource(this,android.net.Uri.parse(r.url),h);ijkPlayer.setOnPreparedListener(mp->{loading.setVisibility(View.GONE);mp.start();});ijkPlayer.setOnErrorListener((mp,what,extra)->{loading.setVisibility(View.GONE);Log.e("LazyTV-IJK","IJK LIVE fallback failed what="+what+" extra="+extra);return true;});ijkPlayer.prepareAsync();}catch(Exception e){usingIjk=false;if(ijkSurface!=null)ijkSurface.setVisibility(View.GONE);playerView.setVisibility(View.VISIBLE);Log.e("LazyTV-IJK","IJK LIVE fallback failed",e);}}
 private void playResolved(StreamItem item,ResolvedStream r){lastResolved=r;idle.setVisibility(View.GONE);current=item;ijkFallbackTried=false;usingIjk=false;if(ijkPlayer!=null){try{ijkPlayer.stop();}catch(Exception ignored){}}if(ijkSurface!=null)ijkSurface.setVisibility(View.GONE);readySince=0L;currentIndex=shown.indexOf(item);try{resolvedHost=new java.net.URL(r.url).getHost();}catch(Exception ignored){resolvedHost="n/a";}usingVlc=false;if(vlcPlayer!=null)vlcPlayer.stop();if(vlcSurface!=null)vlcSurface.setVisibility(View.GONE);playerView.setVisibility(View.VISIBLE);http.setDefaultRequestProperties(r.headers);MediaItem.Builder m=new MediaItem.Builder().setUri(Uri.parse(r.url));String u=r.url.toLowerCase(Locale.US),st=r.streamType==null?"":r.streamType.toLowerCase(Locale.US);/* Do not force a container from Stalker/M3U labels. Media3 sniffs unknown URLs itself; if that fails, VLC then IJK handle the provider format. */if(u.contains(".m3u8")||st.contains("hls")||st.contains("m3u8"))m.setMimeType(MimeTypes.APPLICATION_M3U8);else if(u.matches(".*\\.(mp4|m4v)(\\?.*)?$")||u.contains("extension=mp4")||st.equals("mp4"))m.setMimeType(MimeTypes.VIDEO_MP4);player.setMediaItem(m.build(),true);player.prepare();player.play();title.setText(item.name);String now=r.metadata.get("epg_now"),next=r.metadata.get("epg_next");epg.setText((now==null?"":"Now: "+now)+(next==null?"":"\\nNext: "+next));((Button)findViewById(R.id.live_favorite)).setText(favorites.contains(sourceId(),item)?"★ Favorite":"☆ Favorite");channelsView.invalidateViews();overlayChannels.invalidateViews();}
